q="""
WITH sources AS (SELECT s.* FROM novel_source_item s WHERE s.channel_app_id='00de5521-d075-4472-87eb-cc5d1732f4d0' AND s.deleted_at IS NULL),valid_previews AS (SELECT s.id source_id,s.novel_id,count(c.id) n,min(c.created_at) created_at FROM sources s JOIN novel_chapter c ON c.novel_id=s.novel_id JOIN novel_chapter_content cc ON cc.novel_chapter_id=c.id WHERE c.deleted_at IS NULL AND c.status='preview' AND btrim(cc.body)<>'' GROUP BY s.id,s.novel_id), candidates AS (SELECT s.id source_id,s.novel_id,s.source_locale,s.created_at FROM sources s JOIN novel n ON n.id=s.novel_id WHERE n.deleted_at IS NULL AND s.status='linked' AND s.source_locale='en' AND EXISTS(SELECT 1 FROM promo_link p WHERE p.novel_source_item_id=s.id AND p.deleted_at IS NULL AND p.status='fetched' AND p.upstream_code_present) AND NOT EXISTS(SELECT 1 FROM valid_previews v WHERE v.source_id=s.id) AND NOT EXISTS(SELECT 1 FROM novel_chapter c WHERE c.novel_id=s.novel_id AND c.status='withdrawn') AND NOT EXISTS(SELECT 1 FROM channel_sync_task_item ti JOIN channel_sync_task t ON t.id=ti.task_id WHERE ti.novel_source_item_id=s.id AND t.task_type='moboreader.preview_refresh.v1' AND (ti.status IN ('pending','processing') OR t.status IN ('pending','processing'))))
SELECT json_build_object('at',clock_timestamp(),'capabilities',(SELECT json_object_agg(capability_key,status) FROM channel_capability WHERE channel_app_id='00de5521-d075-4472-87eb-cc5d1732f4d0'),'manualReview',(SELECT count(*) FROM side_effect_intent WHERE channel_app_id='00de5521-d075-4472-87eb-cc5d1732f4d0' AND status='manual_review_required'),'validPreviews',(SELECT json_agg(v ORDER BY v.created_at,v.source_id) FROM valid_previews v),'candidateCount',(SELECT count(*) FROM candidates),'selected',(SELECT json_agg(x) FROM (SELECT source_id,novel_id,source_locale FROM candidates ORDER BY created_at,source_id LIMIT 10) x),'publishedArticles',(SELECT count(*) FROM article a JOIN promo_link p ON p.id=a.promo_link_id WHERE p.channel_app_id='00de5521-d075-4472-87eb-cc5d1732f4d0' AND a.status='published' AND a.deleted_at IS NULL));
"""
raw=sql(q);x=json.JSONDecoder().raw_decode(raw[raw.index('{'):])[0]
print('C_PRECHECK='+json.dumps(x),flush=True)
assert x['manualReview']==635 and x['capabilities']=={'claimPromo':'registered_disabled','getlistpc':'registered_disabled','getbydataid':'registered_disabled','getchapterinfo':'registered_disabled'}
assert x['candidateCount']>=5 and 5<=len(x['selected'])<=10
assert not ({r['source_id'] for r in x['selected']} & {r['source_id'] for r in (x['validPreviews'] or [])})
ids={s:json.loads(run(['docker','inspect',n]).stdout)[0]['Id'] for s,n in NAMES.items()}
print('CONTAINER_IDS_BEFORE='+json.dumps(ids),flush=True)
print('C_PRECHECK_READONLY=PASS',flush=True)
